"use client";

import { Eye, EyeOff, Mail } from "lucide-react";
import { useState } from "react";


export const Logo = () => (
  <svg width="135" height="81" viewBox="0 0 135 81" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
    <rect width="134.386" height="80.8549" fill="url(#pattern0_225_1030)" />
    <defs>
      <pattern id="pattern0_225_1030" patternContentUnits="objectBoundingBox" width="1" height="1">
        <use xlinkHref="#image0_225_1030" transform="matrix(0.00207469 0 0 0.00344828 0 -0.00689655)" />
      </pattern>
      <image id="image0_225_1030" width="482" height="292" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
    </defs>
  </svg>
);


export default function page() {
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const handlesubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const currentTarget = e.currentTarget as HTMLFormElement;
    const formdata = new FormData(currentTarget);
    const email = formdata.get("email");
    const password = formdata.get('password');
    
    await new Promise((resolve) => setTimeout(resolve, 3000))
    try {
      console.log(email, password)

    }
    catch {
      console.log("caught the error")
    }
    finally {
      setLoading(false)
    }

  }

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <form onSubmit={handlesubmit} className="bg-white w-full max-w-md rounded-2xl shadow-lg md:p-8 p-4">

        <div className="flex justify-center mb-3">
          <Logo />
        </div>

        {/* Title */}
        <h2 className="text-center text-2xl font-semibold mb-1">
          Welcome back
        </h2>
        <p className="text-center text-light-gray mb-4">
          Login with your email and admin password
        </p>

        {/* Email Field */}
        <div className="mb-5">
          <label className="block mb-1 font-medium text-black ">
            Email Address
          </label>
          <div className="relative">
            <input
              required
              type="email"
              name="email"
              id="email"
              placeholder="Enter your email"
              className="w-full border autofillbg border-[#DADADA] rounded-lg py-3 px-4 pr-10 outline-none  focus:border-primary transition-colors duration-500"
            />
            <span className="absolute right-3 top-3.5 ">
              <Mail className="text-[#8C8C8C]" />
            </span>
          </div>
        </div>

        {/* Password Field */}
        <div className="mb-7">
          <label className="block mb-1 font-medium text-black">
            Password
          </label>
          <div className="relative">
            <input
              type={showPassword ? "text" : "password"}
              required
              name="password"
              id="password"
              placeholder="Enter password"
              className="w-full border border-[#DADADA] autofillbg rounded-lg py-3 px-4 pr-10 outline-none focus:border-primary transition-colors duration-500"
            />
            <span
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-3.5 text-[#8C8C8C] cursor-pointer select-none"
            >
              {!showPassword ? <EyeOff /> : <Eye />}
            </span>
          </div>
        </div>

        {/* Login Button */}
        <button className="w-full py-3 rounded-lg bg-primary transition text-black font-semibold hover:cursor-pointer">
          {
            loading ? "Loging ..." : "Login"
          }
        </button>
      </form>
    </div>
  );
}
